// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  createApplicationBackend,
  openApplicationStore,
} from "../packages/app-backend/src/index.js";
import { session as appSession } from "../packages/app-backend/src/schema.js";
import {
  appCookie,
  appTestIdentity,
  type BackendFixture,
  backendFixture,
} from "./backend-fixture.js";
import { ownerAuthFixture } from "./owner-auth-fixture.js";

describe("independent application identity HTTP boundary", () => {
  let fixture: BackendFixture;
  const siblings: BackendFixture[] = [];
  beforeEach(async () => {
    fixture = await backendFixture();
  });
  afterEach(async () => {
    await fixture.close();
    await Promise.all(siblings.splice(0).map((other) => other.close()));
  });

  it("T-AC-53 T-AC-54 signs up, signs in and signs out a real application user", async () => {
    const user = await fixture.register();
    expect(user.user).toMatchObject({ email: appTestIdentity.email, name: appTestIdentity.name });
    expect(user.cookie).toBeTruthy();
    const session = await fixture.request("/auth/get-session", {
      headers: { cookie: user.cookie },
    });
    expect(session.status).toBe(200);
    expect(await session.json()).toMatchObject({ user: { id: user.user.id } });
    expect((await fixture.json("/auth/sign-out", {}, { cookie: user.cookie })).status).toBe(200);
    const signedOut = await fixture.request("/auth/get-session", {
      headers: { cookie: user.cookie },
    });
    expect(await signedOut.json()).toBeNull();
    const signedIn = await fixture.json("/auth/sign-in/email", {
      email: appTestIdentity.email,
      password: appTestIdentity.password,
    });
    expect(signedIn.status).toBe(200);
    expect(appCookie(signedIn)).toBeTruthy();
  });

  it("T-AC-53 allows the same email independently in different project cells", async () => {
    const other = await backendFixture();
    siblings.push(other);
    const a = await fixture.register();
    const b = await other.register();
    expect(a.user.id).not.toBe(b.user.id);
    for (const [target, cookie] of [
      [other, a.cookie],
      [fixture, b.cookie],
    ] as const) {
      const response = await target.request("/auth/get-session", { headers: { cookie } });
      expect(response.status).toBe(200);
      expect(await response.json()).toBeNull();
    }
  });

  it("T-AC-53 does not authenticate a development cookie in another environment of that project", async () => {
    const other = await backendFixture({
      scope: { projectId: fixture.scope.projectId, environmentId: randomUUID() },
    });
    siblings.push(other);
    const user = await fixture.register();
    await other.register();
    const response = await other.request("/auth/get-session", { headers: { cookie: user.cookie } });
    expect(await response.json()).toBeNull();
  });

  it("T-AC-53 never exchanges owner and application session authority", async () => {
    const owner = await ownerAuthFixture();
    try {
      const ownerSession = await owner.session();
      const user = await fixture.register();
      const appResponse = await fixture.request("/auth/get-session", {
        headers: { cookie: ownerSession.cookie },
      });
      expect(await appResponse.json()).toBeNull();
      const ownerResponse = await owner.request("/api/v1/projects", {
        headers: { cookie: user.cookie },
      });
      expect(ownerResponse.status).toBe(401);
    } finally {
      await owner.close();
    }
  });

  it("T-AC-53 T-AC-54 preserves app users and valid sessions across a real store reopen", async () => {
    const user = await fixture.register();
    await fixture.restart();
    const response = await fixture.request("/auth/get-session", {
      headers: { cookie: user.cookie },
    });
    expect(response.status).toBe(200);
    expect(await response.json()).toMatchObject({ user: { id: user.user.id } });
    const duplicate = await fixture.json("/auth/sign-up/email", appTestIdentity);
    expect(duplicate.status).toBeGreaterThanOrEqual(400);
    expect(duplicate.status).toBeLessThan(500);
  });

  it("T-AC-53 refuses to reuse another cell's persisted application store", async () => {
    await fixture.runtime.close();
    let unexpected: Awaited<ReturnType<typeof openApplicationStore>> | undefined;
    try {
      await expect(
        openApplicationStore({
          dataDir: fixture.dataDir,
          scope: { projectId: randomUUID(), environmentId: randomUUID() },
        }).then((store) => {
          unexpected = store;
          return store;
        }),
      ).rejects.toThrow();
    } finally {
      await unexpected?.close();
    }
  });

  it("T-AC-53 refuses a second live application runtime or writer for the same cell", async () => {
    await expect(
      createApplicationBackend({ ...fixture.configuration, store: fixture.store }),
    ).rejects.toMatchObject({ code: "INSTANCE_LOCKED" });
    await expect(
      openApplicationStore({ dataDir: fixture.dataDir, scope: fixture.scope }),
    ).rejects.toMatchObject({ code: "INSTANCE_LOCKED" });
    expect((await fixture.register()).user.email).toBe(appTestIdentity.email);
  });

  it.each([
    ["X-Godseye-Project", randomUUID()],
    ["X-Godseye-Environment", randomUUID()],
    ["origin", "https://untrusted.example.test"],
    ["host", "untrusted.example.test"],
  ])("T-AC-53 T-AC-54 rejects a foreign %s before creating identity", async (header, value) => {
    const response = await fixture.json("/auth/sign-up/email", appTestIdentity, {
      [header]: value,
    });
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
    expect(response.headers.getSetCookie()).toHaveLength(0);
    expect((await fixture.json("/auth/sign-up/email", appTestIdentity)).status).toBe(200);
  });

  it("T-AC-54 refuses omitted cell headers instead of selecting a default project", async () => {
    const response = await fixture.runtime.app.request(
      new URL("/api/app/v1/auth/sign-up/email", fixture.baseUrl),
      {
        method: "POST",
        headers: { origin: fixture.baseUrl, "content-type": "application/json" },
        body: JSON.stringify(appTestIdentity),
      },
    );
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
  });

  it.each(["role", "projectId", "environmentId", "admin", "actor"])(
    "T-AC-54 rejects caller authority field %s on signup",
    async (field) => {
      const response = await fixture.json("/auth/sign-up/email", {
        ...appTestIdentity,
        [field]: "owner",
      });
      expect(response.status).toBe(422);
      expect(await response.text()).not.toContain(appTestIdentity.password);
    },
  );

  it("T-AC-54 leaves unconfigured OAuth and native administration routes unavailable", async () => {
    const user = await fixture.register();
    for (const path of ["/sign-in/social", "/delete-user", "/update-user", "/admin/list-users"]) {
      const response = await fixture.json(`/auth${path}`, {}, { cookie: user.cookie });
      expect(response.status, path).toBe(404);
    }
  });

  it("T-AC-54 gives generic signin failure without leaking account or supplied material", async () => {
    await fixture.register();
    const marker = `Synthetic-wrong-value-${randomUUID()}`;
    const response = await fixture.json("/auth/sign-in/email", {
      email: appTestIdentity.email,
      password: marker,
    });
    expect(response.status).toBe(401);
    const text = await response.text();
    expect(text).not.toContain(marker);
    expect(response.headers.getSetCookie()).toHaveLength(0);
  });

  it("T-AC-55 fences new authentication when the application's lifecycle is held", async () => {
    fixture.lifecycle.available = false;
    fixture.lifecycle.epoch++;
    const response = await fixture.json("/auth/sign-up/email", appTestIdentity);
    expect(response.status).toBe(423);
    expect(response.headers.getSetCookie()).toHaveLength(0);
    fixture.lifecycle.available = true;
    expect((await fixture.json("/auth/sign-up/email", appTestIdentity)).status).toBe(200);
  });

  it("T-AC-54 rejects malformed JSON and unsupported methods without a server failure", async () => {
    const malformed = await fixture.request("/auth/sign-up/email", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: "{",
    });
    expect(malformed.status).toBe(400);
    const getSignup = await fixture.request("/auth/sign-up/email");
    expect(getSignup.status).toBe(404);
  });

  it("T-AC-54 enforces explicit registration disablement without creating an account", async () => {
    const closed = await backendFixture({ registrationEnabled: false });
    siblings.push(closed);
    const response = await closed.json("/auth/sign-up/email", appTestIdentity);
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
    expect(response.headers.getSetCookie()).toHaveLength(0);
    expect((await closed.runtime.snapshot()).auth.users).toBe(0);
  });

  it("T-AC-54 expires the real database session rather than trusting a valid cookie signature", async () => {
    const registered = await fixture.register();
    await fixture.store.db
      .update(appSession)
      .set({ expiresAt: new Date(Date.now() - 1000) })
      .where(eq(appSession.userId, registered.user.id));
    const response = await fixture.request("/auth/get-session", {
      headers: { cookie: registered.cookie },
    });
    expect(await response.json()).toBeNull();
    expect(
      (await fixture.request("/files", { headers: { cookie: registered.cookie } })).status,
    ).toBe(401);
  });

  it("T-AC-54 revokes an exact public session ID without revealing native session material", async () => {
    const registered = await fixture.register();
    const list = await fixture.request("/auth/list-sessions", {
      headers: { cookie: registered.cookie },
    });
    expect(list.status).toBe(200);
    const sessions = (await list.json()) as { id: string; expiresAt: string }[];
    expect(sessions.length).toBeGreaterThan(0);
    expect(sessions.every((row) => !Object.hasOwn(row, "token"))).toBe(true);
    const selected = sessions[0];
    if (!selected) throw new Error("Synthetic session missing");
    const revoked = await fixture.json(
      "/auth/revoke-session",
      { sessionId: selected.id },
      { cookie: registered.cookie },
    );
    expect(revoked.status).toBe(200);
    expect(await revoked.json()).toEqual({ revoked: true });
    expect(
      await (
        await fixture.request("/auth/get-session", { headers: { cookie: registered.cookie } })
      ).json(),
    ).toBeNull();
  });
});
